function buildPdiMetaSql(){
  const v = state.vault;
  const esc = s => String(s||'').replace(/'/g, "''");
  const sourceConnName = `${v.name}_source`;
  const stagingConnName = `${v.name}_staging`;
  const dataVaultConnName = `${v.name}_datavault`;
  return `-- =========================================================
-- Metadata reference data
-- Generated by Data Vault Studio — review host/port/credentials before running.
-- REQUIRED FIXED IDS: the load engine runs with
-- id_data_vault=1 pinned in .env (PARAMS_STAGE / PARAMS_VAULT), so the
-- reference rows MUST land at connections 1/2/3, data vault 1, source
-- system 1 — one vault per target database in this release. The TRUNCATE
-- ... CASCADE resets the reference tables AND their dependent
-- instrumentation rows (run history) so re-running is always consistent.
-- =========================================================

SET ROLE pdi_meta;

TRUNCATE pdi_meta.ref_source_systems, pdi_meta.ref_data_vaults, pdi_meta.ref_connections CASCADE;

INSERT INTO pdi_meta.ref_connections
  (id_connection, name, type, description, host_name, database_name, port_number, user_name, password, instance_name)
VALUES
  (1, '${esc(sourceConnName)}', '${esc(DIALECTS[v.dialect].label)}', 'Source connection for ${esc(v.name)}', '${esc(v.srcHost)}', '${esc(v.srcDatabase)}', ${v.srcPort ? `${Number(v.srcPort) || 'NULL'}` : 'NULL'}, '${esc(v.srcUser)}', '${esc(v.srcPassword)}', NULL),
  (2, '${esc(stagingConnName)}', 'PostgreSQL', 'Staging connection for ${esc(v.name)}', '${esc(v.dvHost)}', '${esc(v.dvDatabase)}', ${v.dvPort ? `${Number(v.dvPort) || 'NULL'}` : 'NULL'}, 'staging', '${esc(v.dvPassword)}', NULL),
  (3, '${esc(dataVaultConnName)}', 'PostgreSQL', 'Data vault connection for ${esc(v.name)}', '${esc(v.dvHost)}', '${esc(v.dvDatabase)}', ${v.dvPort ? `${Number(v.dvPort) || 'NULL'}` : 'NULL'}, 'data_vault', '${esc(v.dvPassword)}', NULL);

INSERT INTO pdi_meta.ref_data_vaults
  (id_data_vault, data_vault_name, data_vault_description, ind_current)
VALUES
  (1, '${esc(v.vaultDbName)}', '${esc(v.vaultDescription)}', 1);

INSERT INTO pdi_meta.ref_source_systems
  (id_srcsys, cod_srcsys, description, id_source_connection, id_staging_connection, staging_days_to_load_default, ind_archive_staging_tables)
VALUES
  (1, '${esc(v.srcCod)}', '${esc(v.srcDescription)}', 1, 2, ${incrementalDaysToLoadDefault()}, 0);

RESET ROLE;
`;
}

/* ---- xlsx workbook ---- */
const SHEET_HEADERS = {
  data_vault: ['id_data_vault','data_vault_name','data_vault_description','ind_current'],
  connections: ['name','description'],
  source_systems: ['id_srcsys','cod_srcsys','description','source_connection','staging_connection','staging_days_to_load_default','ind_archive_staging_tables'],
  source_tables: ['source_system','table_name','table_description','staging_table_name','source_concat','ind_stage_this_table','ind_staging_is_incremental','increment_date_column','staging_load_group_order','staging_sql_override','process_in_subruntypes'],
  hubs: ['hub_name','hub_description','hub_key','hub_business_key','hub_source','hub_source_hash_key','hub_source_business_key','hub_source_surrogate_key','hub_source_order','ind_current','ind_last_seen_dts','ind_status_sat','process_in_subruntypes'],
  links: (()=>{
    const h = ['link_name','link_key','link_description','ind_current','source_concat','link_source_order'];
    for (let i=1;i<=10;i++) h.push(`hub_${i}`,`link_hub_${i}_key_column`,`source_hub_${i}_hash_key`);
    h.push('lnk_bk_columns','lnk_no_bk_columns','ind_last_seen_dts','ind_status_sat','lnk_group_key_column','lnk_no_group_key_columns','process_in_subruntypes');
    return h;
  })(),
  link_attributes: ['link_name','source_concat','attribute_number','attribute_source_column','attribute_target_column','ind_current'],
  hub_satellites: ['sat_name','sat_key','sat_description','sat_hub','ind_current','source_concat','source_hub_hash_key','attribute_number','attribute_source_column','attribute_target_column','ind_multiactive_extra_key_column','process_in_subruntypes'],
  link_satellites: (()=>{
    const h = ['sat_name','sat_key','sat_description','sat_link','ind_current','source_concat'];
    for (let i=1;i<=10;i++) h.push(`source_hub_${i}_hash_key`);
    for (let i=1;i<=5;i++) h.push(`source_lnk_key_attribute_${i}`);
    h.push('attribute_number','attribute_source_column','attribute_target_column','process_in_subruntypes');
    return h;
  })(),
  // Keep this final notes sheet so generated workbooks follow the
  // supplied base_template.xlsx tab structure exactly. It is intentionally
  // header-only unless future metadata notes are added.
  Sheet10: ['notes'],
};

